"""Read-only posthoc explanation; never chooses or changes a model."""
import argparse,csv
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('--results',type=Path,required=True);a=p.parse_args()
fields=list(csv.DictReader((a.results/'posthoc_field_diagnostics.csv').open()));geometry=list(csv.DictReader((a.results/'posthoc_role_geometry.csv').open()));effects=list(csv.DictReader((a.results/'paired_effects.csv').open()));summary=list(csv.DictReader((a.results/'summary.csv').open()))
def eff(task,label):
 r=next(r for r in effects if (r['dataset'],r['comparison'],r['operating_point'])==(task,label,'pot'));return f"{100*float(r['average_precision_delta_mean']):+.2f}"
def field(task,name,key):return f"{100*np.mean([float(r[key]) for r in fields if (r['dataset'],r['base'],r['field'])==(task,'cm',name)]):.2f}"
def geo(task,v):return f"{100*float(next(r for r in geometry if (r['dataset'],r['variant'])==(task,v))['teacher_geometry_AP']):.2f}"
def ap(task,v):return f"{100*float(next(r for r in summary if (r['dataset'],r['family'],r['variant'],r['operating_point'])==(task,'himvh',v,'pot'))['average_precision_mean']):.2f}"
t=['## 事后诊断：已定位的影响与仍未解决的问题','','以下诊断在全部模型、评分、阈值和独立核验完成后进行。测试标签只用于解释逐字段误差与输入几何的关系，不参与拟合、阈值或挑选主版本。不得把以下最高数值当作新增主方法成绩。详见[诊断作用范围](posthoc_scope.json)。','','### HUGE：主要损失不是单独的分角色尺度', '',f'**BankSim：** 去角色标识AP变化{eff("banksim","去角色标识")}个百分点；从32维方向数值到16维角色对齐压缩，变化{eff("banksim","对齐及压缩")}；再分角色中心为{eff("banksim","分角色中心")}，再分角色尺度为{eff("banksim","分角色尺度")}。最大的退步发生在“对齐及压缩”这一步，不能简单归咎于分角色标准化；这个对照仍包含维数与方向编码变化。双通道恢复原数值信息之后相对aligned仅变化{eff("banksim","恢复原数值通道")}，表明保留信息并不保证原损失能正确使用它。', '',f'用固定测试图输入重新计算HUGE的HALO几何教师信号，仅作事后诊断：legacy的AP为{geo("banksim","legacy")}%、aligned为{geo("banksim","aligned")}%、dual为{geo("banksim","dual")}%。输入几何本身已发生大幅改变；训练蒸馏和排序所依据的罕见度与欺诈标签关系弱化，是与消融相符的解释。此处不是训练好的HUGE输出，也不是预先登记的候选检测器，不能拿该诊断AP宣称主榜获胜；更不能在看标签后翻转教师或分数。', '',f'**S-FFSD：** 去角色标识{eff("s_ffsd","去角色标识")}个百分点，对齐压缩{eff("s_ffsd","对齐及压缩")}，分角色中心{eff("s_ffsd","分角色中心")}，分角色尺度{eff("s_ffsd","分角色尺度")}。尺度调整在这个任务反而有益，所以不存在跨数据集统一“删除角色信息一定更好”的结论。dual保留信息但新主方案仍不及上一轮role；双通道下加分角色尺度的消融可以描述，但不能据此事后改换主版本。', '', '目前的HUGE改进尝试不应替换上一轮结果。此次证据支持继续研究不破坏原教师几何的角色条件建模，但还没有完成该后续设计，也没有可发表的稳健收益。', '', '### HIMVH：尺度问题得到缓解，欺诈相关权重仍未解决', '',f'**BankSim-cm：** 原始字段均值中amount占校准平均总误差{field("banksim","amount","raw_cal_share")}%，gender占{field("banksim","gender","raw_cal_share")}%，但它们逐字段重构误差的测试AP分别只有{field("banksim","amount","raw_field_AP")}%和{field("banksim","gender","raw_field_AP")}%；category只占{field("banksim","category","raw_cal_share")}%，对应AP为{field("banksim","category","raw_field_AP")}%。尾证据校准后这些字段的平均贡献都接近20%，减弱了原始误差单位和量级的支配。这与主方案AP由{ap("banksim","cm_field")}%提高到{ap("banksim","cm_tail")}%一致，但逐字段AP只是一种事后解释，不用于指定权重。', '',f'**S-FFSD-cm：** amount原贡献{field("s_ffsd","amount","raw_cal_share")}%，尾证据后约{field("s_ffsd","amount","tail_cal_share")}%；location原贡献{field("s_ffsd","location","raw_cal_share")}%，尾证据后约{field("s_ffsd","location","tail_cal_share")}%。对应逐字段误差AP分别为{field("s_ffsd","amount","raw_field_AP")}%、{field("s_ffsd","location","raw_field_AP")}%。降低金额字段的量级支配与新主方案{ap("s_ffsd","cm_tail")}%的收益相符，但排序仍低于该任务常数AP参照38.87%，未解决真实欺诈语义匹配。', '',f'**不能只报告好看的基线。** cm_tail在BankSim的AP{ap("banksim","cm_tail")}%仍低于已有cm_flat的{ap("banksim","cm_flat")}%；S-FFSD为{ap("s_ffsd","cm_tail")}%对{ap("s_ffsd","cm_flat")}%。cm_tail_flat消融为{ap("banksim","cm_tail_flat")}%／{ap("s_ffsd","cm_tail_flat")}%，高于固定主方案，但它仍只属于消融，不按测试成绩提升为主方法。BankSim抽样上下文m_tail的AP{ap("banksim","m_tail")}%也优于完整上下文cm_tail，说明字段评分修正不能抵消所有训练上下文问题。', '', '正相关冗余权重不保证识别欺诈价值：相关的类别／交易关系字段可能同时携带有效线索，下调它们会损失检测信息。最大字段法也可能把无害的罕见字段放大。字段尾证据统一的是罕见度而不是标签相关性，零标签条件下这两者仍有距离。经验尾部超过校准最大值时会饱和；本轮逐字段超上界比例极小（详见CSV），不能把主要退步直接归因于饱和。', '', '[54条字段误差诊断](posthoc_field_diagnostics.csv) · [16条输入几何诊断](posthoc_role_geometry.csv)。新的权重或训练目标需先另立协议并用独立留出数据验证，本轮不再按这批测试成绩迭代。','']
(a.results/'posthoc_interpretation_CN.md').write_text('\n'.join(t))
